refentry.refsect1:
  &reftitle.description;

&style.procedural;

   intfalsenullgrapheme_strlen
   stringstring



   Get string length in grapheme units (not bytes or characters)

&reftitle.parameters;




   string



     The string being measured for length. It must be a valid UTF-8 string.

  &reftitle.examples;

   grapheme_strlen example


<?php

$char_a_ring_nfd = "a\xCC\x8A";  // 'LATIN SMALL LETTER A WITH RING ABOVE' (U+00E5) normalization form "D"
$char_o_diaeresis_nfd = "o\xCC\x88"; // 'LATIN SMALL LETTER O WITH DIAERESIS' (U+00F6) normalization form "D"

print grapheme_strlen( 'abc' . $char_a_ring_nfd . $char_o_diaeresis_nfd . $char_a_ring_nfd);

?>



  &example.outputs;


6



   Handling invalid UTF-8 input

    grapheme_strlen returns &null; or &false; on failure, including
    when the input is not valid UTF-8.
    Use intl_get_error_code and intl_error_name
    to retrieve the ICU error details.



<?php

$string = "\xFF"; // invalid UTF-8 byte sequence
$length = grapheme_strlen($string);

if (!is_int($length)) {
    $code = intl_get_error_code();
    printf("grapheme_strlen() failed: %s (%d)\n", intl_error_name($code), $code);
} else {
    echo $length, PHP_EOL;
}

?>


   &example.outputs;


grapheme_strlen() failed: U_INVALID_CHAR_FOUND (10)

&reftitle.seealso;
Unicode Text Segmentation: Grapheme Cluster Boundaries
